// Extract skills needed based on handoff reason
const items = [];

for (const item of $input.all()) {
  const reason = item.json.reason || '';
  const priority = item.json.priority || 'medium';

  // Determine required skills based on reason
  let requiredSkills = [];

  if (reason.includes('billing') || reason.includes('payment')) {
    requiredSkills.push('billing');
  } else if (reason.includes('technical') || reason.includes('bug')) {
    requiredSkills.push('technical');
  } else if (reason.includes('sales') || reason.includes('upgrade')) {
    requiredSkills.push('sales');
  } else {
    requiredSkills.push('general');
  }

  // Add sentiment-based skill requirement
  if (item.json.sentiment_score && item.json.sentiment_score < 0.3) {
    requiredSkills.push('conflict_resolution');
  }

  items.push({
    json: {
      ...item.json,
      requiredSkills: requiredSkills,
      isUrgent: priority === 'urgent' || priority === 'high'
    }
  });
}

return items;

// Merge handoff request data with agent data
const handoffData = $('Analyze Handoff Requirements').all()[0].json;
const agentData = $input.all()[0].json;

return [{
  json: {
    // Handoff request data
    handoffId: handoffData.id,
    phoneNumber: handoffData.phone_number,
    reason: handoffData.reason,
    priority: handoffData.priority,
    conversationContext: handoffData.conversation_context,
    sentimentScore: handoffData.sentiment_score,
    contactName: handoffData.contact_name || 'Unknown User',
    languagePreference: handoffData.language_preference || 'en',
    waitTimeSeconds: Math.floor(handoffData.wait_time_seconds),

    // Agent data
    agentId: agentData.agent_id,
    agentName: agentData.agent_name,
    agentEmail: agentData.email,
    agentSlackUserId: agentData.slack_user_id,
    agentSkills: agentData.skills,

    // Additional metadata
    assignedAt: new Date().toISOString(),
    isUrgent: handoffData.isUrgent
  }
}];

// Prepare Slack notification message
const handoffData = $('Merge Handoff & Agent Data').all()[0].json;

// Format conversation context preview
let contextPreview = 'No previous messages';
if (handoffData.conversationContext && Array.isArray(handoffData.conversationContext)) {
  const recentMessages = handoffData.conversationContext.slice(-5);
  contextPreview = recentMessages
    .map(msg => `${msg.role === 'user' ? '👤 User' : '🤖 AI'}: ${msg.content.substring(0, 100)}...`)
    .join('\n');
}

// Determine urgency emoji and color
const urgencyEmoji = handoffData.isUrgent ? '🚨' : '⚠️';
const priorityColor = {
  'urgent': '#FF0000',
  'high': '#FF6600',
  'medium': '#FFAA00',
  'low': '#00AA00'
}[handoffData.priority] || '#FFAA00';

// Format wait time
const waitMinutes = Math.floor(handoffData.waitTimeSeconds / 60);
const waitSeconds = handoffData.waitTimeSeconds % 60;
const waitTime = waitMinutes > 0 
  ? `${waitMinutes}m ${waitSeconds}s`
  : `${waitSeconds}s`;

// Sentiment indicator
const sentimentEmoji = handoffData.sentimentScore < 0.3 ? '😟' 
  : handoffData.sentimentScore < 0.6 ? '😐' 
  : '😊';

return [{
  json: {
    ...handoffData,
    slackMessage: {
      channel: $env.SLACK_HANDOFF_CHANNEL || '#customer-support',
      text: `${urgencyEmoji} New Handoff Request`,
      blocks: [
        {
          type: 'header',
          text: {
            type: 'plain_text',
            text: `${urgencyEmoji} New Handoff Request - ${handoffData.priority.toUpperCase()} Priority`
          }
        },
        {
          type: 'section',
          fields: [
            {
              type: 'mrkdwn',
              text: `*Customer:*\n${handoffData.contactName}`
            },
            {
              type: 'mrkdwn',
              text: `*Phone:*\n${handoffData.phoneNumber}`
            },
            {
              type: 'mrkdwn',
              text: `*Assigned Agent:*\n<@${handoffData.agentSlackUserId || handoffData.agentId}>`
            },
            {
              type: 'mrkdwn',
              text: `*Wait Time:*\n${waitTime}`
            },
            {
              type: 'mrkdwn',
              text: `*Reason:*\n${handoffData.reason}`
            },
            {
              type: 'mrkdwn',
              text: `*Sentiment:*\n${sentimentEmoji} ${handoffData.sentimentScore ? (handoffData.sentimentScore * 100).toFixed(0) + '%' : 'N/A'}`
            }
          ]
        },
        {
          type: 'section',
          text: {
            type: 'mrkdwn',
            text: `*Recent Conversation:*\n\`\`\`${contextPreview}\`\`\``
          }
        },
        {
          type: 'actions',
          elements: [
            {
              type: 'button',
              text: {
                type: 'plain_text',
                text: '✅ Accept Handoff'
              },
              style: 'primary',
              value: handoffData.handoffId,
              action_id: 'accept_handoff'
            },
            {
              type: 'button',
              text: {
                type: 'plain_text',
                text: '📞 View Full History'
              },
              value: handoffData.phoneNumber,
              action_id: 'view_history'
            },
            {
              type: 'button',
              text: {
                type: 'plain_text',
                text: '🔄 Reassign'
              },
              value: handoffData.handoffId,
              action_id: 'reassign_handoff'
            }
          ]
        },
        {
          type: 'context',
          elements: [
            {
              type: 'mrkdwn',
              text: `Handoff ID: ${handoffData.handoffId} | Language: ${handoffData.languagePreference} | Assigned: <!date^${Math.floor(Date.now() / 1000)}^{date_short_pretty} at {time}|just now>`
            }
          ]
        }
      ],
      attachments: [
        {
          color: priorityColor,
          text: `💡 *Quick Actions:* Reply to this thread to message the customer directly via WhatsApp`
        }
      ]
    }
  }
}];

// Prepare email notification as backup
const handoffData = $('Merge Handoff & Agent Data').all()[0].json;

// Format conversation context
let contextHtml = '<p><em>No previous messages</em></p>';
if (handoffData.conversationContext && Array.isArray(handoffData.conversationContext)) {
  const recentMessages = handoffData.conversationContext.slice(-10);
  contextHtml = '<div style="background: #f5f5f5; padding: 15px; border-radius: 5px;">';

  recentMessages.forEach(msg => {
    const role = msg.role === 'user' ? '👤 User' : '🤖 AI';
    const bgColor = msg.role === 'user' ? '#e3f2fd' : '#fff3e0';
    contextHtml += `
      <div style="margin: 10px 0; padding: 10px; background: ${bgColor}; border-radius: 3px;">
        <strong>${role}:</strong> ${msg.content}
      </div>
    `;
  });

  contextHtml += '</div>';
}

// Determine priority badge
const priorityBadge = {
  'urgent': '<span style="background: #f44336; color: white; padding: 5px 10px; border-radius: 3px; font-weight: bold;">🚨 URGENT</span>',
  'high': '<span style="background: #ff9800; color: white; padding: 5px 10px; border-radius: 3px; font-weight: bold;">⚠️ HIGH</span>',
  'medium': '<span style="background: #ffc107; color: white; padding: 5px 10px; border-radius: 3px; font-weight: bold;">⚠️ MEDIUM</span>',
  'low': '<span style="background: #4caf50; color: white; padding: 5px 10px; border-radius: 3px; font-weight: bold;">ℹ️ LOW</span>'
}[handoffData.priority] || '';

const waitMinutes = Math.floor(handoffData.waitTimeSeconds / 60);
const sentimentPercent = handoffData.sentimentScore ? (handoffData.sentimentScore * 100).toFixed(0) : 'N/A';

const emailHtml = `
<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8">
  <style>
    body { font-family: Arial, sans-serif; line-height: 1.6; color: #333; }
    .container { max-width: 600px; margin: 0 auto; padding: 20px; }
    .header { background: #1976d2; color: white; padding: 20px; border-radius: 5px 5px 0 0; }
    .content { background: white; padding: 20px; border: 1px solid #ddd; border-top: none; }
    .info-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 15px; margin: 20px 0; }
    .info-item { padding: 10px; background: #f9f9f9; border-left: 3px solid #1976d2; }
    .label { font-weight: bold; color: #666; font-size: 12px; }
    .value { font-size: 16px; margin-top: 5px; }
    .button { display: inline-block; padding: 12px 24px; background: #1976d2; color: white; text-decoration: none; border-radius: 5px; margin: 10px 5px; }
    .footer { text-align: center; margin-top: 20px; color: #666; font-size: 12px; }
  </style>
</head>
<body>
  <div class="container">
    <div class="header">
      <h1 style="margin: 0;">🔔 New Handoff Assignment</h1>
      <p style="margin: 10px 0 0 0;">You have been assigned a customer handoff</p>
    </div>

    <div class="content">
      <div style="margin: 20px 0;">
        ${priorityBadge}
      </div>

      <div class="info-grid">
        <div class="info-item">
          <div class="label">CUSTOMER</div>
          <div class="value">${handoffData.contactName}</div>
        </div>
        <div class="info-item">
          <div class="label">PHONE NUMBER</div>
          <div class="value">${handoffData.phoneNumber}</div>
        </div>
        <div class="info-item">
          <div class="label">HANDOFF REASON</div>
          <div class="value">${handoffData.reason}</div>
        </div>
        <div class="info-item">
          <div class="label">WAIT TIME</div>
          <div class="value">${waitMinutes} minutes</div>
        </div>
        <div class="info-item">
          <div class="label">SENTIMENT SCORE</div>
          <div class="value">${sentimentPercent}%</div>
        </div>
        <div class="info-item">
          <div class="label">LANGUAGE</div>
          <div class="value">${handoffData.languagePreference.toUpperCase()}</div>
        </div>
      </div>

      <h3>Recent Conversation History</h3>
      ${contextHtml}

      <div style="margin-top: 30px; text-align: center;">
        <a href="${$env.N8N_URL || 'https://your-n8n-instance.com'}/workflow" class="button">Access n8n Dashboard</a>
        <a href="${$env.SLACK_WORKSPACE_URL || 'https://slack.com'}" class="button">Open Slack</a>
      </div>

      <div class="footer">
        <p>Handoff ID: ${handoffData.handoffId}</p>
        <p>Assigned at ${new Date(handoffData.assignedAt).toLocaleString()}</p>
        <p>This is an automated notification from WhatsApp Support Agent</p>
      </div>
    </div>
  </div>
</body>
</html>
`;

return [{
  json: {
    ...handoffData,
    emailSubject: `🔔 New ${handoffData.priority.toUpperCase()} Priority Handoff - ${handoffData.contactName}`,
    emailHtml: emailHtml,
    emailTo: handoffData.agentEmail || $env.FALLBACK_AGENT_EMAIL
  }
}];
